window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d5b0493b27c6ca48"]={"versions": [{"id": "FIG-d5b0493b27c6ca48", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Dateistruktur- und Inklusionsdiagramm (Header File Structure Diagram) für das Betriebssystem (OS) innerhalb der BSW-Schicht der AUTOSAR Classic Platform. Es visualisiert die Inklusionsbeziehungen des zentralen Modul-Headers <code>Os.h</code> zu Standardtyp-, Konfigurations- und Speicherkartierungs-Dateien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>OS</code>: Übergeordneter BSW-Modulrahmen, der die OS-Dateistruktur umschließt.\n</li><li><code>Os.h</code>: Zentraler Header-File des Betriebssystems, der nach außen für BSW-Module und Applikationen bereitgestellt wird und die OS-API deklariert.\n</li><li><code>Std_Types.h</code>: Globaler Header für AUTOSAR-Standarddatentypen (<code>Std_ReturnType</code>, Basistypen).\n</li><li><code>Os_Cfg.h</code>: Generierter, modulspezifischer Konfigurations-Header des Betriebssystems für statisch konfigurierte OS-Objekte (Tasks, Events, Alarme, Ressourcen).\n</li><li><code>MemMap.h</code>: Zentraler Speicherkartierungs-Header zur Steuerung der Memory-Allocation-Pragmas für Code und Daten des Betriebssystems.\n</li><li>Relationen: Gerichtete Kanten mit Beschriftung <code>includes</code> von <code>Os.h</code> zu <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>MemMap.h</code> zur Darstellung von Präprozessor-Inklusionen (<code>#include</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Kompilierzeit- und Inklusionsdiagramm stellt die Abbildung kein dynamisches Laufzeitverhalten dar. Zur Präprozessor- bzw. Kompilierungszeit bindet <code>Os.h</code> die Header <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>MemMap.h</code> ein, wodurch Standardtypen, konfigurierte OS-Objekte und Speicherzuordnungs-Makros vor der Deklaration der Betriebssystem-Schnittstellen und Datenstrukturen definiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Festlegung: Implementierungen des AUTOSAR OS müssen sicherstellen, dass <code>Os.h</code> die Header <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>MemMap.h</code> inkludiert.\n</li><li>Modulentwickler und Anwender inkludieren primär <code>Os.h</code>, um Zugriff auf alle OS-Dienste zu erhalten, ohne <code>Std_Types.h</code> oder <code>Os_Cfg.h</code> manuell vorab einbinden zu müssen.\n</li><li><code>MemMap.h</code> dient der Zuordnung von OS-Konstanten, -Variablen und -Codeabschnitten in die konfigurierten Speicherbereiche; zirkuläre Header-Abhängigkeiten sind strikt zu vermeiden.\n</li></ul>"}, {"id": "FIG-c0d06e362c263f49", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Dateistruktur- und Inklusionsdiagramm (Header File Structure Diagram) für das Betriebssystem (OS) innerhalb der BSW-Schicht der AUTOSAR Classic Platform. Es visualisiert die Inklusionsbeziehungen des zentralen Modul-Headers <code>Os.h</code> zu Standardtyp-, Konfigurations- und Speicherkartierungs-Dateien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>OS</code>: Übergeordneter BSW-Modulrahmen, der die OS-Dateistruktur umschließt.\n</li><li><code>Os.h</code>: Zentraler Header-File des Betriebssystems, der nach außen für BSW-Module und Applikationen bereitgestellt wird und die OS-API deklariert.\n</li><li><code>Std_Types.h</code>: Globaler Header für AUTOSAR-Standarddatentypen (<code>Std_ReturnType</code>, Basistypen).\n</li><li><code>Os_Cfg.h</code>: Generierter, modulspezifischer Konfigurations-Header des Betriebssystems für statisch konfigurierte OS-Objekte (Tasks, Events, Alarme, Ressourcen).\n</li><li><code>MemMap.h</code>: Zentraler Speicherkartierungs-Header zur Steuerung der Memory-Allocation-Pragmas für Code und Daten des Betriebssystems.\n</li><li>Relationen: Gerichtete Kanten mit Beschriftung <code>includes</code> von <code>Os.h</code> zu <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>MemMap.h</code> zur Darstellung von Präprozessor-Inklusionen (<code>#include</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Kompilierzeit- und Inklusionsdiagramm stellt die Abbildung kein dynamisches Laufzeitverhalten dar. Zur Präprozessor- bzw. Kompilierungszeit bindet <code>Os.h</code> die Header <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>MemMap.h</code> ein, wodurch Standardtypen, konfigurierte OS-Objekte und Speicherzuordnungs-Makros vor der Deklaration der Betriebssystem-Schnittstellen und Datenstrukturen definiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Festlegung: Implementierungen des AUTOSAR OS müssen sicherstellen, dass <code>Os.h</code> die Header <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>MemMap.h</code> inkludiert.\n</li><li>Modulentwickler und Anwender inkludieren primär <code>Os.h</code>, um Zugriff auf alle OS-Dienste zu erhalten, ohne <code>Std_Types.h</code> oder <code>Os_Cfg.h</code> manuell vorab einbinden zu müssen.\n</li><li><code>MemMap.h</code> dient der Zuordnung von OS-Konstanten, -Variablen und -Codeabschnitten in die konfigurierten Speicherbereiche; zirkuläre Header-Abhängigkeiten sind strikt zu vermeiden.\n</li></ul>"}, {"id": "FIG-202c08c0afea2293", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Dateistruktur- und Inklusionsdiagramm (Header File Structure Diagram) für das Betriebssystem (OS) innerhalb der BSW-Schicht der AUTOSAR Classic Platform. Es visualisiert die Inklusionsbeziehungen des zentralen Modul-Headers <code>Os.h</code> zu Standardtyp-, Konfigurations-, Speicherkartierungs- und RTE-Typ-Dateien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>OS</code>: Übergeordneter BSW-Modulrahmen, der die OS-Dateistruktur umschließt.\n</li><li><code>Os.h</code>: Zentraler Header-File des Betriebssystems, der nach außen für BSW-Module und Applikationen bereitgestellt wird und die OS-API deklariert.\n</li><li><code>Rte_Os_Type.h</code>: Von der RTE generierter Typ-Header, der OS-relevante RTE-Typen bzw. anwendungsbezogene Typdefinitionen für das OS bereitstellt.\n</li><li><code>Std_Types.h</code>: Globaler Header für AUTOSAR-Standarddatentypen (<code>Std_ReturnType</code>, Basistypen).\n</li><li><code>Os_Cfg.h</code>: Generierter, modulspezifischer Konfigurations-Header des Betriebssystems für statisch konfigurierte OS-Objekte.\n</li><li><code>MemMap.h</code>: Zentraler Speicherkartierungs-Header zur Steuerung der Memory-Allocation-Pragmas für Code und Daten des Betriebssystems.\n</li><li>Relationen: Gerichtete Kanten mit Beschriftung <code>includes</code> von <code>Os.h</code> zu <code>Rte_Os_Type.h</code>, <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>MemMap.h</code> zur Darstellung von Präprozessor-Inklusionen (<code>#include</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Kompilierzeit- und Inklusionsdiagramm stellt die Abbildung kein dynamisches Laufzeitverhalten dar. Zur Präprozessor- bzw. Kompilierungszeit bindet <code>Os.h</code> die Header <code>Rte_Os_Type.h</code>, <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>MemMap.h</code> ein, wodurch RTE-Typen, Standardtypen, konfigurierte OS-Objekte und Speicherzuordnungs-Makros vor der Deklaration der Betriebssystem-Schnittstellen und Datenstrukturen definiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Festlegung: Implementierungen des AUTOSAR OS müssen sicherstellen, dass <code>Os.h</code> die Header <code>Rte_Os_Type.h</code>, <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>MemMap.h</code> inkludiert.\n</li><li>Die Aufnahme von <code>Rte_Os_Type.h</code> formalisiert die Kopplung zwischen RTE und Betriebssystem: Generierungswerkzeuge müssen sicherstellen, dass <code>Rte_Os_Type.h</code> vor der Übersetzung des OS zur Verfügung steht.\n</li><li>Modulentwickler und Anwender inkludieren primär <code>Os.h</code>, um Zugriff auf alle OS-Dienste und zugehörige Datentypen zu erhalten; zirkuläre Abhängigkeiten zwischen RTE- und OS-Headern sind zu vermeiden.\n</li></ul>"}, {"id": "FIG-4222313a72f32d8b", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Dateistruktur- und Inklusionsdiagramm (Header File Structure Diagram) für das Betriebssystem (OS) innerhalb der BSW-Schicht der AUTOSAR Classic Platform. Es visualisiert die Inklusionsbeziehungen des zentralen Modul-Headers <code>Os.h</code> zu Standardtyp-, Konfigurations-, Speicherkartierungs- und RTE-Typ-Dateien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>OS</code>: Übergeordneter BSW-Modulrahmen, der die OS-Dateistruktur umschließt.\n</li><li><code>Os.h</code>: Zentraler Header-File des Betriebssystems, der nach außen für BSW-Module und Applikationen bereitgestellt wird und die OS-API deklariert.\n</li><li><code>Rte_Os_Type.h</code>: Von der RTE generierter Typ-Header für OS-relevante Datentypen.\n</li><li><code>Std_Types.h</code>: Globaler Header für AUTOSAR-Standarddatentypen.\n</li><li><code>Os_Cfg.h</code>: Generierter, modulspezifischer Konfigurations-Header des Betriebssystems.\n</li><li><code>Os_MemMap.h</code>: Modulspezifischer Speicherkartierungs-Header des Betriebssystems zur Steuerung der Compiler-Pragmas für OS-spezifischen Code und Daten (ersetzt das generische <code>MemMap.h</code>).\n</li><li>Relationen: Gerichtete Kanten mit Beschriftung <code>includes</code> von <code>Os.h</code> zu <code>Rte_Os_Type.h</code>, <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>Os_MemMap.h</code> zur Darstellung von Präprozessor-Inklusionen (<code>#include</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Kompilierzeit- und Inklusionsdiagramm stellt die Abbildung kein dynamisches Laufzeitverhalten dar. Zur Präprozessor- bzw. Kompilierungszeit bindet <code>Os.h</code> die Header <code>Rte_Os_Type.h</code>, <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>Os_MemMap.h</code> ein, wodurch RTE-Typen, Standardtypen, konfigurierte OS-Objekte und modulspezifische Speicherzuordnungs-Makros vor der Deklaration der Betriebssystem-Schnittstellen und Datenstrukturen definiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Festlegung: Implementierungen des AUTOSAR OS müssen sicherstellen, dass <code>Os.h</code> die Header <code>Rte_Os_Type.h</code>, <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und den modulspezifischen <code>Os_MemMap.h</code> inkludiert.\n</li><li>Die Umstellung von <code>MemMap.h</code> auf <code>Os_MemMap.h</code> folgt dem modularisierten Speicherkonzept von AUTOSAR, wodurch Namensraum- und Mehrfachinklusionsprobleme globaler Memory-Mapping-Dateien vermieden werden.\n</li><li>Modulentwickler müssen sicherstellen, dass die Speicherabschnittsdefinitionen im modulspezifischen <code>Os_MemMap.h</code> für das OS bereitgestellt werden.\n</li></ul>"}, {"id": "FIG-6c65a512df18035c", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Dateistruktur- und Inklusionsdiagramm (Header File Structure Diagram) für das Betriebssystem (OS) innerhalb der BSW-Schicht der AUTOSAR Classic Platform. Es visualisiert die Inklusionsbeziehungen des zentralen Modul-Headers <code>Os.h</code> zu Standardtyp-, Konfigurations-, Speicherkartierungs- und RTE-Typ-Dateien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>OS</code>: Übergeordneter BSW-Modulrahmen, der die OS-Dateistruktur umschließt.\n</li><li><code>Os.h</code>: Zentraler Header-File des Betriebssystems, der nach außen für BSW-Module und Applikationen bereitgestellt wird und die OS-API deklariert.\n</li><li><code>Rte_Type.h</code>: Zentraler Datentyp-Header der RTE, der anwendungs- und BSW-übergreifende Datentypen für das Betriebssystem deklariert (ersetzt <code>Rte_Os_Type.h</code>).\n</li><li><code>Std_Types.h</code>: Globaler Header für AUTOSAR-Standarddatentypen.\n</li><li><code>Os_Cfg.h</code>: Generierter, modulspezifischer Konfigurations-Header des Betriebssystems.\n</li><li><code>Os_MemMap.h</code>: Modulspezifischer Speicherkartierungs-Header des Betriebssystems zur Steuerung der Compiler-Pragmas für OS-spezifischen Code und Daten.\n</li><li>Relationen: Gerichtete Kanten mit Beschriftung <code>includes</code> von <code>Os.h</code> zu <code>Rte_Type.h</code>, <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>Os_MemMap.h</code> zur Darstellung von Präprozessor-Inklusionen (<code>#include</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Kompilierzeit- und Inklusionsdiagramm stellt die Abbildung kein dynamisches Laufzeitverhalten dar. Zur Präprozessor- bzw. Kompilierungszeit bindet <code>Os.h</code> die Header <code>Rte_Type.h</code>, <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>Os_MemMap.h</code> ein, wodurch zentrale RTE-Typen, Standardtypen, konfigurierte OS-Objekte und modulspezifische Speicherzuordnungs-Makros vor der Deklaration der Betriebssystem-Schnittstellen und Datenstrukturen definiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Festlegung: Implementierungen des AUTOSAR OS müssen sicherstellen, dass <code>Os.h</code> die Header <code>Rte_Type.h</code>, <code>Std_Types.h</code>, <code>Os_Cfg.h</code> und <code>Os_MemMap.h</code> inkludiert.\n</li><li>Die Ersetzung von <code>Rte_Os_Type.h</code> durch <code>Rte_Type.h</code> harmonisiert die Typinklusion mit dem allgemeinen AUTOSAR-RTE-Header-Konzept; <code>Rte_Type.h</code> muss vor der Kompilierung des Betriebssystems generiert worden sein.\n</li><li>Entwickler müssen beachten, dass OS-Module nun direkt von der zentralen Typdatei <code>Rte_Type.h</code> abhängen.\n</li></ul>"}], "trans": [{"from": "FIG-d5b0493b27c6ca48", "to": "FIG-c0d06e362c263f49", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c0d06e362c263f49", "to": "FIG-202c08c0afea2293", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neuer Header <code>Rte_Os_Type.h</code> hinzugefügt.\n</li><li>Neue Inklusionsbeziehung (<code>includes</code>) von <code>Os.h</code> auf <code>Rte_Os_Type.h</code> ergänzt.\n</li></ul>"}, {"from": "FIG-202c08c0afea2293", "to": "FIG-4222313a72f32d8b", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Header <code>MemMap.h</code> durch modulspezifischen Header <code>Os_MemMap.h</code> ersetzt.\n</li></ul>"}, {"from": "FIG-4222313a72f32d8b", "to": "FIG-6c65a512df18035c", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Header <code>Rte_Os_Type.h</code> durch zentralen RTE-Header <code>Rte_Type.h</code> ersetzt.\n</li></ul>"}]};
